# generates font5x7.h: 5x7 glyphs (7 bytes per glyph, bit 4 = leftmost pixel) for ASCII 32..95 (upper case, digits, punctuation)
G = {}
def g(ch, art): G[ch] = [r for r in art.split('/')]
g(' ', '...../...../...../...../...../...../.....')
g('A', '.###./#...#/#...#/#####/#...#/#...#/#...#'); g('B', '####./#...#/#...#/####./#...#/#...#/####.'); g('C', '.####/#..../#..../#..../#..../#..../.####')
g('D', '####./#...#/#...#/#...#/#...#/#...#/####.'); g('E', '#####/#..../#..../####./#..../#..../#####'); g('F', '#####/#..../#..../####./#..../#..../#....')
g('G', '.####/#..../#..../#..##/#...#/#...#/.###.'); g('H', '#...#/#...#/#...#/#####/#...#/#...#/#...#'); g('I', '.###./..#../..#../..#../..#../..#../.###.')
g('J', '..###/...#./...#./...#./#..#./#..#./.##..'); g('K', '#...#/#..#./#.#../##.../#.#../#..#./#...#'); g('L', '#..../#..../#..../#..../#..../#..../#####')
g('M', '#...#/##.##/#.#.#/#.#.#/#...#/#...#/#...#'); g('N', '#...#/##..#/#.#.#/#..##/#...#/#...#/#...#'); g('O', '.###./#...#/#...#/#...#/#...#/#...#/.###.')
g('P', '####./#...#/#...#/####./#..../#..../#....'); g('Q', '.###./#...#/#...#/#...#/#.#.#/#..#./.##.#'); g('R', '####./#...#/#...#/####./#.#../#..#./#...#')
g('S', '.####/#..../#..../.###./....#/....#/####.'); g('T', '#####/..#../..#../..#../..#../..#../..#..'); g('U', '#...#/#...#/#...#/#...#/#...#/#...#/.###.')
g('V', '#...#/#...#/#...#/#...#/#...#/.#.#./..#..'); g('W', '#...#/#...#/#...#/#.#.#/#.#.#/##.##/#...#'); g('X', '#...#/#...#/.#.#./..#../.#.#./#...#/#...#')
g('Y', '#...#/#...#/.#.#./..#../..#../..#../..#..'); g('Z', '#####/....#/...#./..#../.#.../#..../#####')
g('0', '.###./#...#/#..##/#.#.#/##..#/#...#/.###.'); g('1', '..#../.##../..#../..#../..#../..#../.###.'); g('2', '.###./#...#/....#/...#./..#../.#.../#####')
g('3', '####./....#/....#/.###./....#/....#/####.'); g('4', '...#./..##./.#.#./#..#./#####/...#./...#.'); g('5', '#####/#..../####./....#/....#/#...#/.###.')
g('6', '.###./#..../#..../####./#...#/#...#/.###.'); g('7', '#####/....#/...#./..#../.#.../.#.../.#...'); g('8', '.###./#...#/#...#/.###./#...#/#...#/.###.')
g('9', '.###./#...#/#...#/.####/....#/....#/.###.')
g('.', '...../...../...../...../...../.##../.##..'); g(',', '...../...../...../...../.##../..#../.#...'); g(':', '...../.##../.##../...../.##../.##../.....')
g(';', '...../.##../.##../...../.##../..#../.#...'); g('!', '..#../..#../..#../..#../..#../...../..#..'); g('?', '.###./#...#/....#/...#./..#../...../..#..')
g('-', '...../...../...../#####/...../...../.....'); g('+', '...../..#../..#../#####/..#../..#../.....'); g('/', '....#/....#/...#./..#../.#.../#..../#....')
g('%', '##..#/##..#/...#./..#../.#.../#..##/#..##'); g('(', '...#./..#../.#.../.#.../.#.../..#../...#.'); g(')', '.#.../..#../...#./...#./...#./..#../.#...')
g('<', '...#./..#../.#.../#..../.#.../..#../...#.'); g('>', '.#.../..#../...#./....#/...#./..#../.#...'); g('=', '...../...../#####/...../#####/...../.....')
g('*', '...../#.#.#/.###./#####/.###./#.#.#/.....'); g("'", '..#../..#../.#.../...../...../...../.....'); g('_', '...../...../...../...../...../...../#####')
g('#', '.#.#./.#.#./#####/.#.#./#####/.#.#./.#.#.'); g('&', '.##../#..#./#.#../.#.../#.#.#/#..#./.##.#'); g('"', '.#.#./.#.#./...../...../...../...../.....')
g('>', '.#.../..#../...#./....#/...#./..#../.#...'); g('@', '.###./#...#/#.###/#.#.#/#.###/#..../.####')
out = ['#ifndef FONT5X7_H', '#define FONT5X7_H', '// font5x7.h - GENERATED by compat/gen_font.py', 'static const unsigned char font5x7[64][7]={']
for c in range(32, 96):
    ch = chr(c); art = G.get(ch)
    if art is None: art = ['.....'] * 7
    rows = [sum((1 << (4 - i)) for i, p in enumerate(r) if p == '#') for r in art]
    out.append('{%s},' % ','.join(str(x) for x in rows) + ' /* %s */' % ch.replace('\\', '?').replace('*/', '* /'))
out.append('};'); out.append('#endif')
open('../source/font5x7.h', 'w').write('\n'.join(out) + '\n')
print('ok')
